// Keep only rows that are worth syncing, and build a version key.
// KEY = row_number + updated_at, so an edited row syncs again but an unchanged
// row is skipped on every following run.
const REQUIRED = ['name', 'email'];

return items.map((item) => {
  const r = item.json;
  const rowNumber = r.row_number || r.rowNumber || '';
  const updatedAt = String(r.updated_at || r.updatedAt || '').trim();

  const missing = REQUIRED.filter((k) => !String(r[k] || '').trim());
  if (missing.length > 0 || !rowNumber) {
    return null;
  }

  return {
    json: {
      eventId: String(rowNumber) + '::' + (updatedAt || 'v1'),
      rowNumber,
      name: String(r.name).trim(),
      email: String(r.email).trim(),
      status: String(r.status || 'new').trim(),
      updatedAt: updatedAt || new Date().toISOString(),
    },
  };
}).filter((x) => x !== null);

// Two jobs, both required:
//  1. Stop the run when the key is already taken. A Postgres node that gets 0 rows emits
//     { success: true } instead of an empty output, so filtering is what actually stops it.
//  2. Put the original payload back. The claim node outputs the SQL row, so without this
//     every downstream node would read fields that no longer exist.
return items
  .filter((item) => item.json && item.json.key)
  .map((item) => ({
    json: Object.assign({}, item.json.payload || {}, { claimKey: item.json.key }),
  }));
